import type { Exam } from '../domain/models/Exam';

export const EXAM_5: Exam = {
  title: "Mock Exam 5",
  subtitle: "Full-Length Simulation E — Multinational & Generative AI",
  sections: [
    // SCENARIO 1 – Multi-national integrated management system (D1/D3/D4 mix)
    { type: "scenario", scenario: "OmniCorp is a multinational conglomerate headquartered in Germany with subsidiaries in Japan, Brazil, and Canada. The group holds ISO 9001 and ISO/IEC 27001 certifications. The board has mandated ISO/IEC 42001 certification for the parent company and its Brazilian subsidiary, which develops generative AI content-moderation tools sold to social-media platforms worldwide. The Japanese subsidiary uses AI only for internal predictive maintenance, while the Canadian subsidiary resells third-party AI analytics. OmniCorp's group CISO proposes a single, consolidated AIMS covering all four entities. The Brazilian subsidiary's AI team has been operating under its own informal AI governance charter for two years.", questions: [
      { question: "The group CISO proposes one consolidated AIMS for all four entities. What is the most significant challenge the organization must address when defining scope under Clause 4.3?", options: ["Determining whether a single Statement of Applicability can reference different Annex A controls for each subsidiary based on their distinct AI activities, risk profiles, and regulatory contexts", "Verifying under Clause 4.4 that each subsidiary's AI processes share identical inputs and outputs so the consolidated AIMS can describe a single integrated process map", "Aligning the consolidated scope with the existing ISO/IEC 27001 ISMS scope statement so the same boundary applies to information security and AI governance"], correct: 0, explanation: "Clause 4.3 requires considering internal/external issues, interested-party requirements, and the interfaces and dependencies between activities. Different subsidiaries face different AI risks and regulatory environments, making a tailored SoA the central challenge. The Clause 4.4 process-map option misreads 4.4, which does not require identical processes across units. Reusing the ISMS boundary ignores that ISO/IEC 42001 scope must be set on its own terms (Clause 4.3), not inherited from another standard." },
      { question: "The Brazilian subsidiary has operated under an informal AI governance charter for two years. How should this be treated during AIMS implementation?", options: ["Retire the charter and replace it with the parent company's AI policy verbatim, since Clause 5.2 requires a single AI policy approved by top management", "Conduct a gap analysis mapping the charter's existing controls to ISO/IEC 42001 requirements, retaining effective practices and formalizing them within the AIMS", "Submit the charter to the certification body for pre-approval before any mapping work begins, since prior practices must be validated before they can feed an AIMS"], correct: 1, explanation: "Best practice is to build on existing effective controls; a gap analysis identifies what to retain and what to enhance. The first distractor misreads Clause 5.2 — a single AI policy does not preclude reusing subsidiary practices that conform. Certification bodies do not pre-approve internal artefacts; they audit conformity later, so the third option invents a step that is not part of ISO/IEC 17021-1 or 42006." },
      { question: "The Canadian subsidiary resells third-party AI analytics without developing or modifying the AI. Must it be included in the AIMS scope?", options: ["No, ISO/IEC 42001 Clause 1 limits applicability to organizations that develop or substantively modify AI systems, which excludes pure resellers", "Yes, organizations that use or provide products or services utilizing AI systems are within scope, regardless of whether they developed the AI", "Only the customer-facing front office of the reseller is in scope, since ISO/IEC 42001 applies role-by-role rather than to the legal entity as a whole"], correct: 1, explanation: "Clause 1 applies to any organization that provides or uses products or services utilizing AI systems; reselling AI analytics counts as providing AI-based services. The first distractor misquotes Clause 1 by narrowing it to developers, which is not what the standard says. The third invents a role-based scoping rule that ISO/IEC 42001 does not establish — scope is set at the organization or defined unit level under Clause 4.3." },
      { question: "OmniCorp must comply with the EU AI Act for its German operations, Brazil's LGPD for data protection, and Japan's AI governance guidelines. How should these be incorporated into the AIMS?", options: ["Capture them only in the Statement of Applicability as additional controls under A.2.4, since legal and regulatory requirements are managed exclusively through Annex A control selection", "Address each jurisdiction's requirements as external issues under Clause 4.1 and interested-party requirements under Clause 4.2, integrating them into a unified risk assessment and control framework", "Treat them as inputs to management review under Clause 9.3 only, since legal compliance is reviewed periodically rather than embedded in the AIMS planning loop"], correct: 1, explanation: "Clauses 4.1 and 4.2 are the gateway for external issues and interested-party requirements; these feed risk assessment and control selection. The first distractor confines compliance to Annex A control selection, but legal requirements must first be identified through 4.1/4.2 before any SoA mapping. The third distractor reduces compliance to a periodic review item, which would leave planning, operations, and risk treatment without legal inputs." },
      { question: "OmniCorp already holds ISO 9001 and ISO/IEC 27001. The implementation team proposes reusing the existing internal audit program without modification. What is the most appropriate response?", options: ["Reuse the existing audit program structure but extend its scope to cover AI-specific requirements, ensure auditors have AI competence, and add AI-related audit criteria from ISO/IEC 42001 Clause 9.2", "Maintain the existing program unchanged for the first surveillance cycle, since the Harmonized Structure makes Clause 9.2 audit criteria identical across the three standards", "Outsource the AIMS audit to an external provider while keeping the integrated program for ISO 9001 and ISO/IEC 27001, since AI audit competence cannot be developed in-house"], correct: 0, explanation: "The Harmonized Structure enables integration, but Clause 9.2 still requires audit criteria that reflect ISO/IEC 42001-specific requirements and auditor competence in AI. The second distractor misreads Annex SL — the structure is shared but criteria must reflect each standard's content. The third distractor invents a constraint: ISO/IEC 42001 9.2 permits internal auditors with appropriate competence and does not require outsourcing." }
    ]},

    // SCENARIO 2 – Generative AI content moderation challenges (D4/D1/D3)
    { type: "scenario", scenario: "StreamSafe develops a generative AI system that automatically moderates user-generated content on social media platforms. The system processes text, images, and video in twelve languages. During operational testing, the team discovers that the model disproportionately flags content from certain cultural contexts as harmful when it is actually benign cultural expression. The data governance lead reveals that 78% of the training data originated from English-language sources. A major client demands real-time explainability for every moderation decision. The product team has been deploying weekly model updates directly to production without formal change control.", questions: [
      { question: "The model disproportionately flags benign cultural expressions from certain contexts. Which Annex A control area is most directly relevant to addressing this issue?", options: ["AI system impact assessment controls (A.5.2–A.5.5), which address how AI outputs affect individuals, groups, and broader society including cultural minorities", "AI system documentation controls (A.6.2.7–A.6.2.8), which require recording moderation rules and decisions so cultural bias can be reviewed retrospectively", "Communication controls (A.3.3 and A.8.3) covering disclosure of moderation criteria to users so affected parties can self-identify discrimination"], correct: 0, explanation: "Cultural bias is a societal-impact issue addressed by the impact-assessment control family in A.5. The documentation distractor cites real controls (A.6.2.7–A.6.2.8) but they target system records, not the bias problem itself; they support investigation rather than prevent or assess the impact. The communication distractor relies on user self-identification, which is downstream and does not satisfy the requirement to assess and treat impacts on affected groups." },
      { question: "The training data is 78% English-language. Under ISO/IEC 42001's data governance requirements, what must the organization do?", options: ["Disclose the imbalance in the system's information for users (A.8.2) so deployers can compensate operationally; data quality treatment is the deployer's responsibility under A.7", "Assess data representativeness as part of data quality management, document the identified gap, treat the associated bias risk, and establish controls for ongoing data quality monitoring", "Re-weight the model's training loss to compensate for the language imbalance and record the adjustment in the model card, completing the data governance obligation"], correct: 1, explanation: "Data governance controls (A.7) require representativeness assessment, treatment of resulting risks, and ongoing monitoring. The first distractor wrongly transfers data-quality responsibility to deployers; A.7 places it with the provider. The third distractor swaps a model-level mitigation for the broader data-governance lifecycle requirement: re-weighting alone does not satisfy assessment, documentation, treatment, and monitoring." },
      { question: "The client demands real-time explainability for every moderation decision. How should this requirement be addressed within the AIMS framework?", options: ["Treat the request as out of scope because Annex A.6.2.8 requires only post-hoc documentation of AI system decisions, not real-time explanations to deployers", "Assess the requirement against the organization's AI policy, determine the appropriate level of explainability as part of risk treatment, document the agreed approach in the client contract, and implement corresponding Annex A transparency controls", "Escalate the request to top management under Clause 5.1 for a binary decision to accept or refuse, since contractual transparency obligations override the risk treatment process"], correct: 1, explanation: "Explainability requirements are a risk-treatment input that should flow through 6.1.3/8.3 and Annex A transparency controls (A.8). The first distractor misuses A.6.2.8: it does not preclude real-time explainability and does not exempt customer commitments. The third distractor short-circuits the AIMS by elevating contracts above risk treatment; Clause 5.1 leadership does not replace 6.1.3 or 8.3 decision-making." },
      { question: "Weekly model updates are deployed to production without formal change control. Which AIMS requirements does this violate?", options: ["Clause 6.3 changes to the AIMS, since weekly model updates constitute changes to the management system itself rather than to AI system operations", "Clause 8.1 operational planning and control, which requires established criteria for processes and implementation of control including management of changes to AI systems", "Clause 7.5.3 control of documented information, since uncontrolled deployments mean version records are not retained as required documented information"], correct: 1, explanation: "Clause 8.1 governs operational planning and control, including change management for AI system operations. The first distractor confuses model deployment changes (operational, 8.1) with changes to the AIMS itself (Clause 6.3, e.g. policy or scope changes). The third distractor narrows the issue to documentation under 7.5.3, but the substantive nonconformity is the absence of operational change controls, not just records." },
      { question: "A platform user files a complaint alleging the AI system censored legitimate political speech. Under which AIMS processes should this complaint be handled?", options: ["Under Annex A.3.3 reporting concerns alone, since complaints from external parties feed a single dedicated reporting channel rather than multiple AIMS processes", "Through the AIMS communication process (Clause 7.4) for handling external communications, feeding into the AI risk assessment (Clause 8.2) to evaluate whether the complaint indicates a systemic issue, and potentially triggering corrective action (Clause 10.2)", "Through Clause 8.4 AI system impact assessment, since complaints about specific decisions are individual impact reviews rather than communication or nonconformity matters"], correct: 1, explanation: "Complaints traverse communication (7.4), feed risk assessment (8.2), and trigger corrective action (10.2) when nonconformity is identified. The first distractor restricts handling to A.3.3 reporting, which is one input but not the whole pathway. The third distractor confuses individual complaints with periodic impact assessments; 8.4 evaluates systems holistically and is not the channel for handling individual reports." }
    ]},

    // SCENARIO 3 – Complex supply chain with AI components (D4/D3)
    { type: "scenario", scenario: "AutoDrive manufactures autonomous vehicle components and uses AI systems sourced from multiple vendors. The perception system comes from Vendor A (a startup with no formal AI governance), the decision-planning module from Vendor B (ISO/IEC 42001 certified), and the natural language interface from Vendor C (a large tech company with proprietary governance). AutoDrive's AIMS team must manage these third-party AI components within their management system. During a recent incident, the perception system misclassified a road obstacle, and AutoDrive could not obtain sufficient technical information from Vendor A to conduct a root cause analysis. The safety officer has raised concerns that Vendor C's governance framework is opaque and may not meet ISO/IEC 42001 expectations.", questions: [
      { question: "AutoDrive cannot obtain technical information from Vendor A for root cause analysis after an incident. What AIMS control deficiency does this reveal?", options: ["A deficiency in Clause 8.4 AI system impact assessment, since impact assessments should have anticipated the obstacle misclassification and required pre-incident technical disclosures", "A deficiency in third-party management controls (A.10.2–A.10.4): the organization should have established contractual requirements for transparency, incident cooperation, and access to technical information from AI suppliers", "A deficiency in Clause 7.5.2 creating documented information, since AutoDrive failed to record Vendor A's technical specifications when first engaging the supplier"], correct: 1, explanation: "Annex A.10 controls cover third-party and supplier requirements, including contractual provisions for transparency and incident cooperation. The first distractor confuses 8.4 (impact assessment of a deployed system) with supplier governance; impact assessments do not by themselves create supplier obligations. The third distractor reduces a contractual gap to a documentation gap; even perfect records of vendor specs would not have unlocked post-incident technical access without a supplier obligation." },
      { question: "Vendor B holds ISO/IEC 42001 certification. Does this eliminate AutoDrive's obligation to assess the decision-planning module's risks?", options: ["Yes, where a supplier holds an accredited ISO/IEC 42001 certificate covering the relevant AI component, A.10.4 permits the integrator to rely on that certification in lieu of its own assessment", "No, AutoDrive must still assess risks of the integrated system including how Vendor B's component interacts with other components, even though Vendor B's certification provides assurance about the vendor's own governance", "Only if AutoDrive's certification is in the same scheme; otherwise mutual recognition under ISO/IEC 17011 is required before reliance is permissible"], correct: 1, explanation: "AIMS responsibility cannot be transferred; integration risks remain with the using organization. The first distractor invents an A.10.4 reliance clause that does not exist — A.10 requires due diligence regardless of supplier certification. The third distractor misuses ISO/IEC 17011, which governs accreditation bodies and has no role in determining whether an integrator must perform its own risk assessment under Clauses 6.1.2 and 8.2." },
      { question: "The safety officer is concerned that Vendor C's proprietary governance framework is opaque. What is the most appropriate AIMS-aligned action?", options: ["Accept Vendor C's framework if independent assurance reports such as SOC 2 Type II are available, since recognized assurance reports satisfy A.10.3 supplier requirements without further bilateral controls", "Define minimum governance requirements based on ISO/IEC 42001 and contractually require Vendor C to demonstrate compliance or provide equivalent assurance, conducting supplier assessments as needed", "Require Vendor C to share its full internal AI governance documentation under NDA so AutoDrive can map it directly against Annex A controls before any further use"], correct: 1, explanation: "A.10 requires the using organization to define and verify its own supplier governance expectations; equivalent assurance is acceptable when justified. The first distractor accepts a SOC 2 report as automatically sufficient, but that report addresses different criteria and does not satisfy AI-specific A.10 expectations. The third distractor demands full disclosure that vendors will rarely provide and is disproportionate; AIMS controls accept demonstrated equivalence rather than full transparency." },
      { question: "AutoDrive integrates AI components from three vendors into a single autonomous system. What AI lifecycle consideration is most critical for the AIMS?", options: ["Defining a single end-to-end SLA covering all three vendors so service performance is monitored uniformly across the integrated system", "Managing the interfaces between AI components throughout the system lifecycle, including integration testing, monitoring component interactions in production, and coordinating updates across vendors", "Verifying under A.6.1.2 that all three vendors follow the same AI development lifecycle methodology to ensure compatibility at integration"], correct: 1, explanation: "Annex A.6.2 lifecycle controls require managing component interfaces, integration, and coordinated updates — emergent risks live at the interfaces. The first distractor reduces lifecycle risk to a contractual SLA; SLAs measure service but do not address technical integration risks. The third distractor misreads A.6.1.2: it requires the using organization to define its own lifecycle process, not to force suppliers onto a common methodology, which is rarely feasible." },
      { question: "After the perception system incident, AutoDrive's corrective action plan focuses solely on switching to a different perception vendor. Is this an adequate corrective action under Clause 10.2?", options: ["Yes, under ISO 9000 terminology replacing the failed component is a correction that simultaneously eliminates the cause of the nonconformity, satisfying 10.2", "No, Clause 10.2 requires analyzing the root cause of the nonconformity; switching vendors addresses the immediate issue but does not address potential systemic gaps in vendor assessment, integration testing, and third-party management processes", "Yes, provided the replacement vendor holds ISO/IEC 42001 certification and AutoDrive's risk register is updated with the new supplier identity"], correct: 1, explanation: "Clause 10.2 distinguishes correction from corrective action: correction eliminates the detected NC, corrective action eliminates the cause to prevent recurrence. The first distractor conflates the two ISO 9000 terms — vendor replacement is a correction, not corrective action. The third distractor treats vendor certification as a sufficient cause-elimination, but systemic gaps in AutoDrive's own vendor assessment and integration testing would persist regardless of which vendor is used." }
    ]},

    // SCENARIO 4 – Leadership and organizational roles in a matrix organization (D3)
    { type: "scenario", scenario: "PharmaTech operates a matrix organization where AI projects report to both the R&D division and the Digital Transformation office. The CEO has endorsed the AI policy but delegated all AIMS responsibilities to the IT Director. The AI ethics committee, composed of external academics, meets quarterly but has no formal authority within the AIMS governance structure. Data scientists report to R&D project leads for technical work but to the Digital Transformation VP for AI governance matters. A recent internal audit found that no single individual is accountable for AI risk treatment decisions, as both divisions assume the other is responsible. The HR department reports that AI competence requirements have not been defined for any role involved in AI system development or operation.", questions: [
      { question: "The CEO endorsed the AI policy but delegated all AIMS responsibilities to the IT Director. Does this satisfy Clause 5.1 leadership requirements?", options: ["Yes, provided the delegation is documented in writing and the IT Director sits on the executive committee, since Clause 5.3 permits full delegation of AIMS leadership to a designated representative", "No, while top management may delegate tasks, Clause 5.1 requires top management to retain accountability for AIMS effectiveness, including personal engagement in ensuring resources, communicating importance, and conducting management reviews", "Yes, since Clause 5.1(a) is satisfied once top management has approved an AI policy, with subsequent leadership activities permissible to delegate to senior management"], correct: 1, explanation: "Clause 5.1 lists ten leadership commitments that top management must demonstrate; accountability cannot be fully delegated. The first distractor misreads Clause 5.3, which is about role assignment and does not authorize transferring 5.1 accountability. The third distractor fixates on policy approval (5.1(b)) and ignores that 5.1(a) explicitly requires top management to take accountability for AIMS effectiveness, which is non-delegable." },
      { question: "The AI ethics committee has no formal authority within the AIMS governance structure. What is the most appropriate corrective action?", options: ["Convert the committee into the management review body under Clause 9.3, with quarterly meetings substituting for management review and authority derived from that role", "Define the committee's role, responsibilities, and authority within the AIMS through Clause 5.3, establishing clear interfaces with decision-making processes such as risk treatment approval and impact assessment review", "Reconstitute the committee as the internal audit team under Clause 9.2 to give it formal authority while preserving its independence from operational management"], correct: 1, explanation: "Clause 5.3 requires assigning roles, responsibilities, and authorities and communicating them. The first distractor wrongly substitutes external academics for management review under 9.3, which must be conducted by top management. The third distractor breaches internal-audit independence requirements (9.2) and conflates ethics oversight with conformity auditing — they are different functions with different competence and reporting lines." },
      { question: "No single individual is accountable for AI risk treatment decisions due to the matrix structure. What AIMS requirement is violated?", options: ["Clause 6.1.3, which requires that risk owners be identified for each treatment option chosen during the risk treatment process", "Clause 5.3, which requires that responsibilities and authorities for relevant roles are assigned and communicated, including clear accountability for AI risk treatment decisions", "Clause 9.3(c), which requires management review to verify accountability arrangements at planned intervals"], correct: 1, explanation: "Clause 5.3 covers organizational roles, responsibilities, and authorities — including unambiguous accountability for risk treatment. The first distractor cites the right standards-family idea (risk owners) but the wrong clause: ISO/IEC 42001 places accountability assignment in 5.3, not in a 6.1.3 risk-owner clause as in ISO/IEC 27001. The third distractor confuses verification (9.3) with the assignment requirement itself; review cannot verify what was never assigned." },
      { question: "AI competence requirements have not been defined for roles involved in AI development and operation. Which clauses are directly implicated?", options: ["Clause 7.2 alone, which requires the organization to determine necessary competence for personnel whose work affects AI performance and to retain documented information as evidence", "Clause 7.2 (competence) for defining required competence, Clause 7.1 (resources) for ensuring adequate human resources, and Clause 7.3 (awareness) for ensuring personnel understand their contribution to AIMS effectiveness", "Clause 7.2 plus A.4.4 human resources, since competence under Clause 7 relies on the Annex A.4 resource controls being implemented first"], correct: 1, explanation: "Multiple support clauses are implicated: 7.1 (resources, including human), 7.2 (competence), and 7.3 (awareness). The first distractor narrows the issue to 7.2 only; it ignores that resources and awareness are also unmet when competence requirements are undefined. The third distractor invents a sequencing dependency between Clause 7 and A.4.4 — Annex A controls support requirements but are not prerequisites for Clause 7 conformity." },
      { question: "Data scientists report to different managers for technical work and AI governance. What risk does this dual-reporting structure create for AIMS effectiveness?", options: ["The principal risk is duplicate documentation of the same activities under both reporting lines, contravening Clause 7.5.3 requirements for control of documented information", "Risk that governance requirements are deprioritized when they conflict with project delivery timelines, and that accountability gaps emerge when neither reporting line takes ownership of AIMS compliance", "The risk is limited to performance evaluation conflicts at year-end review, addressable through aligned KPIs across both reporting lines"], correct: 1, explanation: "Matrix structures create real conflicts between delivery pressure and governance, with accountability gaps as the central risk. The first distractor invents a 7.5.3 violation; documented information control is unaffected by reporting-line geometry. The third distractor reduces a structural governance risk to a year-end HR issue, ignoring the day-to-day decisions that determine whether AIMS controls are followed under delivery pressure." }
    ]},

    // SCENARIO 5 – Performance evaluation and monitoring of AI systems (D5)
    { type: "scenario", scenario: "FinTrust Bank operates five AI systems: credit scoring, anti-money laundering (AML) detection, customer churn prediction, chatbot support, and algorithmic trading. The AIMS has been operational for fourteen months. The performance evaluation team has established KPIs for technical model accuracy but has not defined KPIs for AIMS process effectiveness. Internal audits have been scheduled annually, but the first audit has not yet been conducted. The management review was held six months ago but only discussed financial performance of AI projects, not AIMS effectiveness. The AML detection system's false-positive rate has increased by 40% over six months, but this trend was not identified because monitoring focuses only on monthly snapshots rather than trend analysis.", questions: [
      { question: "KPIs exist for model accuracy but not for AIMS process effectiveness. What does Clause 9.1 specifically require?", options: ["Determination of methods for monitoring, measurement, analysis, and evaluation that focus on AI system outputs and outcomes, with process effectiveness covered under Clause 10.2 instead", "The organization must determine what needs to be monitored and measured, including AIMS process effectiveness and AI system performance, along with methods, timing, and responsibility for evaluation", "Definition of monitoring frequencies aligned to risk severity, with process-level KPIs required only for AI systems classified as high-impact under the organization's risk methodology"], correct: 1, explanation: "Clause 9.1 explicitly requires monitoring AIMS process effectiveness and AI system performance, with methods, timing, and responsibilities. The first distractor wrongly transplants process-effectiveness measurement into 10.2 continual improvement; 9.1 is the source clause. The third distractor invents a risk-tiered exemption that 9.1 does not contain — process-effectiveness monitoring applies regardless of system risk class." },
      { question: "The first internal audit has not been conducted despite fourteen months of AIMS operation. What is the conformity status?", options: ["Conforming, because Clause 9.2 requires internal audits at planned intervals and the first three-year cycle does not begin until the certification audit confirms AIMS readiness", "Non-conforming: while the standard does not mandate a specific frequency, fourteen months without an internal audit does not satisfy Clause 9.2's requirement to conduct audits at planned intervals, especially when the schedule specified annual audits", "Conforming, provided the audit is conducted within six months of the initial certification audit, in line with the timing tolerance set by ISO/IEC 17021-1 for first-cycle organizations"], correct: 1, explanation: "Clause 9.2 requires audits at planned intervals; the organization defined annual, and fourteen months breaches that. The first distractor fabricates a three-year cycle tied to certification — Clause 9.2 applies independently of certification status. The third distractor misuses ISO/IEC 17021-1, which governs certification body audit cycles, not internal audits performed under Clause 9.2." },
      { question: "The management review discussed financial performance of AI projects but not AIMS effectiveness. What required inputs were missing?", options: ["Strategic alignment with the organization's business objectives, since Clause 9.3 prioritizes the connection between AIMS and corporate strategy over operational AIMS data", "Clause 9.3 requires management review inputs including audit results, AI system performance, nonconformities, monitoring results, and changes to external/internal issues relevant to the AIMS", "Resource adequacy assessments, which are the principal Clause 9.3 input under ISO/IEC 42001 because AIMS effectiveness is determined by adequate resourcing"], correct: 1, explanation: "Clause 9.3 enumerates required inputs: status of actions from prior reviews, changes in issues, monitoring/measurement results, audit results, NC and corrective actions, opportunities for improvement, and more. The first distractor cherry-picks strategic alignment as the priority, but 9.3 requires a comprehensive set of inputs. The third distractor elevates resource adequacy to principal status, but it is one input among many — not a priority that excludes the others." },
      { question: "The AML system's false-positive rate increased 40% over six months but was not detected because monitoring uses only monthly snapshots. What improvement is needed?", options: ["Add quarterly comparison reports between snapshots, since monthly snapshots already capture the data and only the comparison cadence is missing for trend visibility", "The monitoring approach should include trend analysis and threshold-based alerting, enabling detection of gradual performance degradation such as model drift before it reaches critical levels", "Replace monthly snapshots with continuous real-time inference logging and shift from periodic monitoring to streaming statistical process control for all AI systems"], correct: 1, explanation: "Trend analysis and threshold alerting are the standard treatment for gradual drift. The first distractor does too little — quarterly comparisons of monthly snapshots are still discrete and prone to lagging detection without explicit thresholds and trend modeling. The third distractor over-engineers — Clause 9.1 requires proportionate monitoring; mandating streaming SPC for every system is disproportionate and not what the standard requires." },
      { question: "FinTrust's chatbot has no performance monitoring at all because it was classified as low-risk. Is this acceptable under the AIMS?", options: ["Yes, the AI system impact assessment under Clause 8.4 may classify low-risk systems as exempt from Clause 9.1 monitoring when impact is below a defined threshold", "No, Clause 9.1 requires monitoring for all AI systems within scope; the depth and frequency may be proportionate to risk level, but complete absence of monitoring is non-conforming", "Yes, provided the chatbot is excluded from the SoA via A.6.2.4 system operation control and the exclusion is justified to the certification body"], correct: 1, explanation: "Clause 9.1 monitoring applies to all in-scope AI systems; depth scales with risk, but absence is non-conforming. The first distractor misuses 8.4: impact assessment informs treatment, not exemption from 9.1. The third distractor misreads SoA — A.6.2.4 is a control, not a scope-exclusion mechanism, and the SoA cannot remove monitoring obligations from in-scope systems under Clause 9.1." }
    ]},

    // SCENARIO 6 – Internal audit challenges in integrated systems (D5/D6)
    { type: "scenario", scenario: "GlobalInsure holds certifications for ISO 9001, ISO/IEC 27001, and ISO/IEC 42001. The internal audit manager has developed an integrated audit program covering all three standards. During the latest integrated audit cycle, the audit team discovers that the AI risk assessment references the information security risk assessment but does not include AI-specific risk criteria. The auditors also find that management review meetings for all three standards are combined, but the agenda template does not include AI-specific inputs required by ISO/IEC 42001 Clause 9.3. One auditor, who is highly experienced in ISO/IEC 27001 but has no AI background, audited the AI operational controls and reported no findings. A junior auditor identifies a potential nonconformity but is overruled by the lead auditor, who argues it is merely an observation.", questions: [
      { question: "The AI risk assessment references the information security risk assessment but lacks AI-specific risk criteria. What is the audit finding?", options: ["Observation: the cross-reference satisfies Clause 6.1.2 baseline requirements, with AI-specific criteria recommended for the next risk assessment cycle", "Nonconformity: while integration is appropriate, the AI risk assessment must include AI-specific risk criteria addressing concerns such as bias, transparency, data quality, and societal impact, which are distinct from information security risks", "Opportunity for improvement: 6.1.2 permits inheriting risk criteria from related management systems provided the inheritance is documented in the risk methodology"], correct: 1, explanation: "Clause 6.1.2 requires AI-specific risk criteria; integration is fine but inheritance does not satisfy the requirement. The first distractor downgrades the issue to an observation — missing AI-specific criteria is a substantive 6.1.2 gap. The third distractor invents an inheritance permission that is not in 6.1.2; the clause requires the organization to define risk criteria for the AIMS, not to import them wholesale from another standard." },
      { question: "Combined management reviews do not include AI-specific inputs. How should this be classified?", options: ["Observation: management review structure is at top management's discretion under Clause 5.1, and the integrated agenda is sufficient if AI topics are discussed in any item", "Nonconformity against Clause 9.3: combined management reviews must still address all required inputs for each standard, and missing AI-specific inputs means ISO/IEC 42001 requirements are not met", "Minor nonconformity against Clause 7.5 only, since the agenda template is documented information that fails to include all required content"], correct: 1, explanation: "Clause 9.3 specifies mandatory inputs; combined reviews must satisfy each standard's requirements. The first distractor wrongly hands content discretion to top management — 9.3 inputs are mandatory, not a leadership choice under 5.1. The third distractor reframes a 9.3 substance gap as a 7.5 documentation gap; missing inputs are not a paperwork issue, they are a management-review conformity issue." },
      { question: "An auditor with ISO/IEC 27001 expertise but no AI background audited AI operational controls and found nothing. What concern does this raise?", options: ["No concern: ISO/IEC 17021-1 permits an experienced lead auditor to delegate AI-specific assessments to a technical expert during follow-up if any concerns later emerge", "The auditor may lack the competence to evaluate AI-specific operational controls effectively, potentially resulting in missed nonconformities; audit team competence must cover both management system and AI-specific knowledge", "The concern is procedural only: under Clause 9.2 the audit programme must rotate auditors annually to avoid familiarity bias, and competence can be developed during rotation"], correct: 1, explanation: "Audit team competence under 9.2 must cover both management-system and AI-specific knowledge; missing competence undermines audit reliability. The first distractor misreads ISO/IEC 17021-1, which applies to certification audits and requires AI competence on the audit team during the audit, not as post-hoc follow-up. The third distractor invents an annual rotation rule — there is none in 9.2; the one-year cooling-off rule applies to auditing one's own work, not rotation." },
      { question: "A junior auditor's potential nonconformity finding is overruled by the lead auditor and classified as an observation. What principle is at stake?", options: ["The principle of audit confidentiality, since findings should be communicated only after lead-auditor review to protect the auditee from premature disclosure of unverified issues", "Audit findings must be based on objective evidence against audit criteria, not on the seniority of the auditor; the lead auditor should evaluate the evidence and justification rather than simply overruling based on judgment", "The principle of audit conclusiveness: under ISO 19011 only the lead auditor formally classifies findings, and the junior auditor's role is limited to evidence collection rather than classification"], correct: 1, explanation: "Audit findings must be evidence-based; ISO 19011 emphasises objectivity and impartiality. The first distractor confuses overruling with confidentiality — confidentiality protects information, not classification. The third distractor misstates ISO 19011: while the lead auditor has overall responsibility, all auditors raise findings based on evidence and findings cannot be downgraded without examining the evidence." },
      { question: "GlobalInsure's integrated audit program must satisfy requirements across three standards. What is the most critical success factor?", options: ["Maintaining a unified audit checklist that maps every clause across the three standards to a single integrated criterion, eliminating duplicate findings", "Ensuring audit criteria, scope, and auditor competence address the specific requirements of each standard, particularly AI-specific requirements that do not exist in ISO 9001 or ISO/IEC 27001", "Aligning the audit cycle with the certification body's surveillance schedule so that internal and external audits cover the same clauses in the same months"], correct: 1, explanation: "Integrated audits must address each standard's unique requirements with appropriate criteria and competence. The first distractor over-unifies: collapsing distinct requirements into a single criterion loses standard-specific content, especially AI-specific clauses without 9001/27001 equivalents. The third distractor confuses internal-audit planning (driven by Clause 9.2) with external-audit cycles, which are governed by 17021-1 and not the right driver for internal audit timing." }
    ]},

    // SCENARIO 7 – Certification process complexities (D6)
    { type: "scenario", scenario: "MediScan AI has completed its AIMS implementation and applied for initial ISO/IEC 42001 certification. During Stage 1, the certification body auditor identifies that the documented AIMS scope excludes the organization's most critical AI system—a radiology diagnostic tool—citing the system's pending regulatory approval. The auditor also notes that the organization has defined AI objectives but cannot demonstrate how they were derived from the AI policy. Stage 2 is conducted eight months later. The audit team finds one major nonconformity (no evidence of AI system impact assessment for any deployed system) and three minor nonconformities. The organization submits a corrective action plan for the major nonconformity, proposing to complete impact assessments within nine months.", questions: [
      { question: "The AIMS scope excludes the radiology diagnostic tool because it is pending regulatory approval. Is this a valid basis for exclusion?", options: ["Yes, Clause 4.3(b) explicitly permits exclusion of AI systems pending regulatory approval since the organization cannot fully control them until approval is granted", "The pending approval status does not by itself justify exclusion; the scope should be based on Clause 4.3 criteria, and excluding the organization's most critical AI system may undermine the AIMS's relevance and credibility with interested parties", "Yes, but only if the organization commits in the SoA to extending the scope within twelve months of regulatory approval, which is the maximum exclusion period"], correct: 1, explanation: "Clause 4.3 sets scope based on context, IPs, interfaces, and dependencies — regulatory-approval status is not an exclusion criterion. The first distractor invents a 4.3(b) exclusion that the standard does not contain. The third distractor invents a twelve-month maximum that has no basis in 42001 or 17021-1; the SoA is not the place to time-box scope exclusions, and the underlying exclusion is invalid in the first place." },
      { question: "AI objectives cannot be traced back to the AI policy. What Clause 6.2 requirement is unmet?", options: ["Clause 6.2 requires objectives to be aligned with AI risk treatment plans rather than the AI policy itself, since policy provides direction and risk treatment provides the operational link", "Clause 6.2 requires AI objectives to be consistent with the AI policy; inability to demonstrate this linkage indicates the objectives may not reflect the organization's stated commitments", "Clause 6.2 requires objectives to be SMART, and traceability to the policy is a quality criterion under Annex C.2 rather than a Clause 6.2 mandatory requirement"], correct: 1, explanation: "Clause 6.2(a) explicitly requires AI objectives to be consistent with the AI policy. The first distractor swaps two related concepts — 6.2 ties objectives to policy, while risk treatment plans are a separate output of 6.1.3. The third distractor misuses Annex C.2: C.2 lists potential AI-related objective topics; it does not relegate consistency-with-policy from a 6.2 requirement to a quality criterion." },
      { question: "Stage 2 is conducted eight months after Stage 1. Is this timing appropriate under ISO/IEC 17021-1?", options: ["Yes, ISO/IEC 17021-1 establishes a twelve-month maximum interval between Stage 1 and Stage 2, so an eight-month gap remains within the permitted window", "Potentially problematic: ISO/IEC 17021-1 requires that Stage 2 be conducted within a timeframe that allows Stage 1 findings to be addressed but not so long that conditions may have significantly changed, typically within six months", "Yes, provided the certification body re-issued the Stage 1 report within thirty days of Stage 2 to confirm that prior findings remain valid"], correct: 1, explanation: "ISO/IEC 17021-1 expects Stage 2 within roughly six months; longer gaps risk changed conditions and may require Stage 1 elements to be repeated. The first distractor invents a twelve-month maximum that 17021-1 does not specify. The third distractor invents a thirty-day re-issuance procedure that does not exist; report dates do not reset the validity window of Stage 1 conclusions." },
      { question: "The organization proposes completing impact assessments for the major nonconformity within nine months. What is the certification body's likely response?", options: ["Accept a phased plan with verification at twelve months, as ISO/IEC 17021-1 sets the maximum verification window for major NCs at one year following Stage 2", "Require resolution within six months, as ISO/IEC 17021-1 indicates that if a major nonconformity cannot be resolved within six months after Stage 2, a partial or full Stage 2 re-audit should be conducted", "Convert the major NC to three minor NCs against the underlying impact-assessment sub-clauses, allowing the standard surveillance cycle to verify closure"], correct: 1, explanation: "ISO/IEC 17021-1 requires major NC verification within roughly six months of Stage 2; failing that triggers a re-audit. The first distractor misstates the verification window as twelve months. The third distractor invents a downgrading mechanism that does not exist — major NCs cannot be subdivided into minors to relax timelines; the classification is based on impact, not on certification-body convenience." },
      { question: "Three minor nonconformities were also identified. What is their impact on the certification decision?", options: ["Minor nonconformities require closure verification on-site within thirty days of the audit, after which the certification decision can proceed", "Minor nonconformities require corrective action plans to be submitted and accepted by the certification body; the certification decision considers whether these corrective actions are adequate and will be implemented", "Minor nonconformities defer the certification decision to the first surveillance audit, where their closure is verified before the certificate is issued"], correct: 1, explanation: "Minors require accepted corrective action plans; the certification body evaluates plan adequacy as part of the decision. The first distractor invents a thirty-day on-site closure rule; minor closure is typically documented and verified at surveillance, not on-site within thirty days. The third distractor wrongly defers the decision; certificates can be issued with accepted plans, with closure verified at the next audit." }
    ]},

    // SCENARIO 8 – Data governance and AI lifecycle (D4)
    { type: "scenario", scenario: "DataMed operates an AI-powered clinical decision support system trained on electronic health records from partnering hospitals. The data pipeline involves receiving de-identified patient data from twelve hospitals, performing data cleaning and feature engineering, training ensemble models, and deploying to a cloud environment. A data quality audit reveals that three hospitals have been sending records with a systematic coding error that affects 15% of diagnoses. The data engineering team fixed the error in the pipeline but did not retrain existing models. Additionally, the organization has no documented data lineage tracking, and the data retention policy was inherited from a general IT policy that does not account for AI training data lifecycle requirements.", questions: [
      { question: "Three hospitals sent records with systematic coding errors affecting 15% of diagnoses. The pipeline was fixed but models were not retrained. What is the AIMS concern?", options: ["The pipeline correction is a Clause 10.2 corrective action and is sufficient because it eliminates the cause; retraining decisions belong to the next planned model release cycle", "Models trained on corrupted data may produce biased or inaccurate outputs; the organization must assess the impact on existing models, determine whether retraining is necessary, and implement controls to prevent similar data quality issues", "The concern is contained because the 15% error rate is below the 20% materiality threshold defined in A.7.4 for triggering retraining of deployed models"], correct: 1, explanation: "Corrupted training data raises an open question about deployed-model integrity; the AIMS must assess impact on existing models and decide on retraining. The first distractor confuses correction (fixing the pipeline) with corrective action (eliminating the cause and consequences); ignoring deployed models leaves the cause partly unaddressed. The third distractor invents a 20% threshold in A.7.4 that does not exist — A.7.4 requires data-quality treatment, not a fixed materiality cutoff." },
      { question: "The organization has no documented data lineage tracking. Which AIMS requirements does this affect?", options: ["Primarily Clause 7.5 documented information, since data lineage is a record-keeping requirement that supports audit trails for AI training data", "Multiple requirements including data governance controls for traceability, AI risk assessment capability for identifying data-related risks, and the ability to conduct effective root cause analysis for AI system issues", "Clause 6.1.4 AI system impact assessment alone, since lineage is required only to demonstrate that data origins were considered in the impact assessment for affected parties"], correct: 1, explanation: "Lineage supports A.7 data governance traceability, AI risk assessment, and incident root-cause analysis. The first distractor narrows the issue to 7.5 records, ignoring that lineage substantively enables risk assessment and investigation, not just record-keeping. The third distractor confines lineage to 6.1.4 impact assessment and misreads the clause — impact assessment uses lineage information but is not the primary AIMS requirement that lineage serves." },
      { question: "The data retention policy was inherited from a general IT policy. What is inadequate about this approach?", options: ["General IT retention policies cover information security retention only, so the gap is solely in alignment with ISO/IEC 27001 Annex A.5.33 rather than ISO/IEC 42001", "AI training data has unique lifecycle requirements including considerations for model retraining, bias testing, regulatory obligations for AI transparency, and the need to maintain data for model validation and audit purposes", "The general IT policy must be replaced rather than supplemented because Annex A.7 prohibits referencing non-AI policies in AI data governance"], correct: 1, explanation: "AI training data has lifecycle needs that general IT policies typically do not address, including retraining, bias verification, AI transparency, and audit trails. The first distractor reframes the gap as an ISMS issue, missing that retention drives AI-specific obligations beyond information security. The third distractor invents a prohibition in A.7 that does not exist — referencing existing IT policies is fine, provided AI-specific requirements are added." },
      { question: "DataMed receives de-identified patient data from twelve hospitals. What third-party data governance control is most important?", options: ["Implementing a single source-of-truth vendor portal that ingests, validates, and rejects non-conforming records automatically before any human review by data engineering", "Establishing data quality agreements with each hospital specifying data standards, error reporting requirements, and responsibilities for data accuracy, along with regular data quality assessments", "Requiring each hospital to provide a SOC 2 Type II report covering data integrity controls, since SOC 2 is the recognized assurance vehicle for upstream data quality"], correct: 1, explanation: "A.7 plus A.10 require data-quality agreements with upstream parties and regular assessments. The first distractor swaps a governance control for a technical pipeline control; automation does not establish responsibility, standards, or accountability for accuracy at source. The third distractor misreads SOC 2 — it addresses service-organization controls for security/confidentiality, not the AI-specific data-quality content that A.7 requires." },
      { question: "The ensemble model combines outputs from multiple sub-models. What AI lifecycle challenge does this create for the AIMS?", options: ["Ensemble models complicate Clause 6.2 objective-setting because each sub-model needs its own measurable objective consistent with the AI policy", "Ensemble models create challenges for explainability, version control, and change management, as each sub-model may require independent monitoring, and interactions between sub-models must be tracked throughout the lifecycle", "Ensemble models must be classified as multiple AI systems under Clause 4.3 scope, with each sub-model holding a separate Statement of Applicability"], correct: 1, explanation: "Ensembles complicate explainability, versioning, change control, and component-interaction monitoring across the lifecycle. The first distractor wrongly forces sub-model-level objectives — 6.2 sets AIMS-level AI objectives, not per-sub-model targets. The third distractor invents a per-sub-model SoA requirement; an SoA is per AIMS, not per system or sub-system, and Clause 4.3 does not require splitting ensembles into separate scopes." }
    ]},

    // SCENARIO 9 – Continual improvement and corrective action (D6/D5)
    { type: "scenario", scenario: "LogiAI provides AI-powered logistics optimization for global shipping companies. After two years of AIMS operation, the management review reveals several patterns: corrective actions from internal audits are consistently closed on time but the same types of nonconformities recur; the AI risk register has not been substantially updated since initial implementation despite significant changes in AI technology and business operations; customer complaints about route optimization errors have increased 25% year-over-year; and the organization's AI competence development program has delivered training to only 30% of personnel in AI-related roles. The continual improvement process consists solely of tracking corrective action closure rates.", questions: [
      { question: "The same types of nonconformities recur despite corrective actions being closed on time. What does this indicate about the corrective action process?", options: ["The process is applying corrections rather than corrective actions, satisfying the immediate response requirement but leaving the cause unaddressed under ISO 9000 terminology", "The corrective actions are likely addressing symptoms rather than root causes; Clause 10.2 requires determining the cause of nonconformities and taking action to ensure they do not recur or occur elsewhere", "The recurrence pattern indicates a Clause 9.2 internal audit competence problem, since recurring NCs would not be raised twice if auditors classified them correctly the first time"], correct: 1, explanation: "Clause 10.2 requires cause analysis and prevention of recurrence; recurrence signals symptom-only treatment. The first distractor makes a correct ISO 9000 distinction but misapplies it — the issue is that purported corrective actions never eliminated the cause, not merely that corrections were misnamed. The third distractor blames audit competence; recurrence reflects ineffective treatment, not auditor classification error — auditors raising the same NC twice are doing their job." },
      { question: "The AI risk register has not been substantially updated in two years. What clause is most directly violated?", options: ["Clause 6.1.2 only, since 6.1.2 establishes the risk assessment process and updating frequency falls under that clause's planned-intervals requirement", "Clauses 6.1.2 and 8.2: the risk assessment process must be applied at planned intervals and when significant changes are proposed or occur, covering both planning and operations", "Clause 6.3 changes to the AIMS, since failing to update the risk register is itself a planned change to the AIMS that was never executed"], correct: 1, explanation: "Both 6.1.2 (planning the risk assessment) and 8.2 (operational risk assessment at planned intervals or when changes occur) apply. The first distractor confines the violation to 6.1.2; in ISO/IEC 42001, ongoing operational risk assessment is in 8.2 and is the more direct violation. The third distractor misuses 6.3, which addresses planned changes to the AIMS, not failures to perform routine risk assessment updates." },
      { question: "Customer complaints about route optimization errors increased 25%. How should this be handled within the AIMS?", options: ["As a Clause 7.4 communication input only, since complaints are external communications and the AIMS handles them through the communication process before any other clause applies", "Through Clause 9.1 monitoring as an indicator of AI system performance degradation, feeding into the risk assessment process and potentially triggering corrective action under Clause 10.2", "Under Annex A.3.3 reporting concerns alone, with the reporting log feeding directly into management review at the next planned interval"], correct: 1, explanation: "Complaints are a 9.1 monitoring signal that should feed risk assessment and trigger 10.2 corrective action when NC is identified. The first distractor stops at communication intake; receipt is necessary but does not address the substantive performance signal. The third distractor restricts handling to A.3.3 logging plus a delayed review, missing that the 25% trend is a performance signal requiring monitoring analysis and corrective action, not just a quarterly report." },
      { question: "Only 30% of personnel in AI-related roles have received competence training. What is the conformity status?", options: ["Conforming under Clause 7.2 if the program prioritises high-risk roles first and a documented schedule covers the remaining 70% within the next two annual training cycles", "Non-conforming with Clause 7.2: the organization must ensure that persons doing work affecting AI system performance have the necessary competence, and 70% of untrained personnel represents a significant gap", "Non-conforming with A.4.2 only, since the gap is in resource allocation for training delivery rather than in the Clause 7.2 competence determination itself"], correct: 1, explanation: "Clause 7.2 requires the organization to ensure competence, not merely to schedule it. The first distractor confuses prioritisation with conformity — phasing is acceptable, but at any point the people currently doing the work must be competent, and 70% are not. The third distractor narrows the issue to A.4.2 resources, ignoring that 7.2 is the clause that requires ensured competence regardless of how resourcing is structured." },
      { question: "Continual improvement is limited to tracking corrective action closure rates. Why is this insufficient under Clause 10.1?", options: ["Closure rates measure efficiency rather than effectiveness, while Clause 10.1 requires effectiveness measurement of corrective actions specifically", "Clause 10.1 requires improving the suitability, adequacy, and effectiveness of the AIMS; this includes proactive improvements based on monitoring trends, technology changes, best practices, and management review outputs, not merely reactive closure of findings", "Clause 10.1 requires improvement metrics to map to each Annex A control area, with a separate KPI per control family rather than a single closure-rate KPI"], correct: 1, explanation: "Clause 10.1 (Continual improvement) requires improving the AIMS as a whole — proactively, not just by closing findings. The first distractor reduces 10.1 to corrective-action effectiveness, which is part of 10.2; 10.1 is broader. The third distractor invents a per-control-family KPI mandate that 10.1 does not impose; the requirement is improvement breadth, not a fixed metric structure." }
    ]},

    // SCENARIO 10 – Generative AI risk and emerging technology (D1/D4)
    { type: "scenario", scenario: "CreativeAI is a marketing agency that recently adopted a large language model (LLM) to generate advertising copy, social media posts, and client communications. The LLM is accessed via API from a third-party provider who updates the model periodically without prior notice. Staff members have begun using the LLM to draft contract language and legal disclaimers without legal review. The organization discovered that the LLM occasionally generates content that closely resembles copyrighted material from competitors. There is no documented acceptable-use policy for generative AI tools. The data protection officer raises concerns that staff are pasting client confidential information into the LLM prompts, potentially exposing it to the third-party provider.", questions: [
      { question: "Staff use the LLM to draft contract language without legal review. What AIMS control gap does this represent?", options: ["A Clause 7.3 awareness gap, since trained staff would self-restrict their LLM use to non-legal contexts without operational controls being needed", "A gap in operational controls (Clause 8.1) for defining acceptable use boundaries, human oversight requirements, and approval workflows for AI-generated outputs in high-stakes contexts", "A gap in A.9.4 use of AI systems for human oversight, addressable solely by adding mandatory legal sign-off to the existing contract template rather than the AIMS"], correct: 1, explanation: "Clause 8.1 operational planning and control covers acceptable-use boundaries, oversight, and approval workflows for high-stakes outputs. The first distractor relies on awareness alone; awareness without operational controls leaves staff free to ignore guidance under deadline pressure. The third distractor cites a real control (A.9.4) but treats it as a single template change; A.9.4 must be implemented through the operational control system that 8.1 establishes, not as an isolated edit." },
      { question: "The LLM generates content resembling copyrighted material. What AIMS requirement is most relevant?", options: ["Clause 8.4 AI system impact assessment alone, since IP infringement is an impact on third-party rights holders rather than an organizational risk", "AI risk assessment (Clause 8.2) should identify intellectual property infringement as a risk, with risk treatment (Clause 8.3) including output review processes, content verification controls, and contractual protections with the LLM provider", "Annex A.7.4 quality of data alone, since IP risk in generative outputs originates from the training data quality of the LLM provider"], correct: 1, explanation: "IP infringement is a risk addressed through 8.2 assessment and 8.3 treatment, including transparency, output review, and supplier contracts. The first distractor confines IP risk to 8.4 impact assessment — impact assessment evaluates effects on parties, but the operational handling sits with risk assessment and treatment. The third distractor narrows the issue to upstream data quality; even with clean data, output controls and contractual protections are the AIMS-side treatments." },
      { question: "The LLM provider updates the model without prior notice. What AIMS challenge does this create?", options: ["The challenge is procedural under A.10.4 only, addressable by adding model-version-change notification to the supplier contract; once notified, change management proceeds normally", "The organization cannot maintain effective change management, impact assessment, or performance monitoring when the underlying model changes unpredictably, potentially altering outputs, introducing new risks, or affecting compliance", "The challenge is limited to Clause 9.1 monitoring frequency, resolvable by switching from monthly to weekly performance baselines so unannounced updates are detected quickly"], correct: 1, explanation: "Unannounced updates affect change management (8.1), impact assessment (8.4), monitoring (9.1), and risk treatment (8.3) simultaneously. The first distractor reduces the issue to a contract clause; even with notice, the model still changes and the AIMS must absorb it. The third distractor reduces the issue to monitoring cadence; faster monitoring detects change but does not address impact assessment or change-control requirements that the unannounced updates undermine." },
      { question: "Staff paste client confidential information into LLM prompts. Which combination of AIMS and related controls is most relevant?", options: ["A.7 data governance alone, since pasting client data into prompts is a data-handling issue resolvable through the AI data governance control family", "Annex A controls on data governance and data quality management, operational controls (Clause 8.1) for AI system use, and the interface with information security management for protecting confidential information in AI contexts", "A.4.6 tooling and computing resources, since the issue is selecting LLM tools that do not retain or transmit prompt content to the provider"], correct: 1, explanation: "The issue spans A.7 data governance, 8.1 operational controls for use, and the ISMS interface for confidentiality protection. The first distractor confines the issue to data governance, missing the operational use controls and the ISMS interface needed for confidentiality. The third distractor reduces the problem to tool selection (A.4.6); even with non-retentive tools, staff conduct, acceptable-use rules, and confidentiality controls remain necessary." },
      { question: "There is no acceptable-use policy for generative AI tools. What is the most comprehensive AIMS-aligned action?", options: ["Add an acceptable-use clause to the AI policy under Clause 5.2, since the AI policy is the highest-level expression of intent and a policy clause is sufficient to drive staff behaviour", "Develop operational procedures (Clause 8.1) defining acceptable use cases, prohibited uses, data handling requirements, output review processes, and human oversight requirements for generative AI, integrated with the overall AI policy and risk treatment framework", "Implement A.9.2 processes for responsible use of AI systems by extending the existing third-party AI use checklist to cover generative tools, without amending the wider AI policy"], correct: 1, explanation: "Acceptable-use rules belong in operational procedures under 8.1, integrated with the AI policy and risk treatment. The first distractor stops at policy text; policy alone does not provide enforceable use cases, prohibited uses, or oversight steps. The third distractor names the right control (A.9.2) but reduces it to a checklist extension and intentionally avoids policy alignment, leaving the AIMS fragmented rather than integrated." }
    ]},

    // STANDALONE QUESTIONS (30 questions)
    { type: "standalone", questions: [
      // Domain 1 – Fundamentals (7 more to reach 17 total with scenarios)
      { question: "ISO/IEC 22989 defines several types of machine learning. Which type uses a reward signal to optimize an agent's behavior through interaction with an environment?", options: ["Supervised learning, where the reward signal acts as a sparse, delayed label that the model regresses against during training", "Reinforcement learning, where the agent learns to maximize cumulative reward through trial-and-error interaction", "Semi-supervised learning, where the reward signal compensates for missing labels by approximating ground truth from environment feedback"], correct: 1, explanation: "ISO/IEC 22989 defines reinforcement learning by the agent-environment interaction with reward signals. The first distractor confuses RL with supervised learning by reframing rewards as labels; rewards are not labels in 22989's definition. The third distractor borrows from semi-supervised learning, which uses a mix of labelled and unlabelled data — not reward signals — and is a different paradigm in the same standard." },
      { question: "Under the EU AI Act, which practice is explicitly prohibited as posing unacceptable risk?", options: ["Emotion-recognition AI used in workplace and educational settings, which is classified as a prohibited practice under Article 5 of the AI Act with no permitted exceptions", "Real-time remote biometric identification systems in publicly accessible spaces by law enforcement, subject to narrow exceptions", "Generative AI systems that produce deepfakes without disclosing the synthetic nature of the content to end users at the point of consumption"], correct: 1, explanation: "Real-time remote biometric ID in public by law enforcement is among the Article 5 prohibitions, with narrow exceptions. The first distractor overstates: emotion recognition in workplace/education is restricted but with carve-outs (e.g., medical/safety) — not without exceptions. The third distractor confuses transparency obligations (Article 50) with prohibitions; non-disclosed deepfakes breach transparency rules but are not Article 5 unacceptable-risk prohibitions." },
      { question: "The NIST AI RMF 'Map' function focuses on which activities?", options: ["Mapping AI system components, dependencies, and data flows so risks can be assigned to specific technical artefacts during risk treatment", "Establishing context, identifying AI risks, and understanding the AI system's impacts across its lifecycle, including stakeholder identification", "Mapping AI risks to NIST control catalogs and selecting technical safeguards that align with organizational risk tolerance"], correct: 1, explanation: "Map establishes context, frames risks, and identifies impacts and stakeholders across the AI lifecycle. The first distractor reduces Map to technical-artefact mapping; that is closer to a system inventory and is not what NIST AI RMF Map prescribes. The third distractor confuses Map with Manage and with NIST 800-53 control selection; control selection is not the purpose of Map." },
      { question: "ISO/IEC 38507 addresses AI governance at the governing body level. What distinguishes governance from management in this context?", options: ["Governance is performed by the AIMS top management group while management is performed by operational AI committees, with both functions reporting to the same executive sponsor", "Governance involves evaluating, directing, and monitoring AI use at the strategic level, while management involves planning, building, running, and monitoring AI systems at the operational level", "Governance is the auditable subset of management activities defined in ISO/IEC 38507 Clause 5, while management activities sit outside the standard's scope"], correct: 1, explanation: "ISO/IEC 38507 distinguishes governing-body responsibilities (evaluate, direct, monitor) from management activities (plan, build, run, monitor). The first distractor blurs the distinction by treating both as different operational committees; the standard separates strategic from operational. The third distractor inverts the relationship: governance is not a subset of management; they are distinct accountability layers in 38507." },
      { question: "According to ISO/IEC TR 24028, which category of threats to AI trustworthiness includes adversarial attacks designed to manipulate AI system inputs?", options: ["Threats from environmental drift, including distribution shift, concept drift, and data drift that arise after deployment without adversarial intent", "Threats from intentional adversarial manipulation, including evasion attacks, data poisoning, and model extraction", "Threats from algorithmic opacity, including lack of explainability and inability to audit decision pathways"], correct: 1, explanation: "ISO/IEC TR 24028 recognises intentional adversarial threats as a distinct category, including evasion, poisoning, and extraction. The first distractor names real phenomena (drift) but they are non-adversarial reliability concerns, not the intentional-attack category. The third distractor describes opacity, which is a different trustworthiness dimension (transparency/explainability) and not the input-manipulation threat class." },
      { question: "What is the primary purpose of ISO/IEC 42006 in the AI standards ecosystem?", options: ["To provide implementation guidance for ISO/IEC 42001 controls, complementing Annex B with detailed how-to material for organizations adopting an AIMS", "To specify requirements for bodies providing audit and certification of AI management systems, ensuring consistent and competent AIMS certification globally", "To establish a competence framework for individual AI auditors, parallel to ISO/IEC 17024 for persons certification in the AI domain"], correct: 1, explanation: "ISO/IEC 42006 specifies requirements for AIMS certification bodies, building on ISO/IEC 17021-1. The first distractor confuses 42006 with implementation guidance; ISO/IEC 42005 and Annex B serve guidance roles. The third distractor confuses 42006 (bodies certifying organizations) with 17024 (bodies certifying persons); 42006 does not establish individual auditor competence schemes directly." },
      { question: "An AI system uses transfer learning, applying knowledge from a pre-trained model to a new domain. Under ISO/IEC 22989, what classification consideration is most relevant?", options: ["Transfer learning is treated as a form of meta-learning under 22989, so the system inherits the meta-learning classification regardless of downstream task scope", "The classification depends on the specific learning techniques used in both the pre-training and fine-tuning phases, and the system remains narrow AI focused on specific tasks", "Transfer learning systems shift classification toward general AI when pre-training data spans multiple domains, even if fine-tuning targets a single task"], correct: 1, explanation: "22989 classifies AI by task scope and approach; transfer learning remains narrow AI defined by its task. The first distractor conflates transfer learning with meta-learning; they are distinct techniques in 22989. The third distractor wrongly elevates broad pre-training to general AI; breadth of pre-training data does not change the narrow/general classification, which depends on operational task scope." },

      // Domain 2 – AIMS requirements (5 questions)
      { question: "The Harmonized Structure (Annex SL) provides common clauses across management system standards. Which clause is unique to ISO/IEC 42001 and does not have a direct equivalent in ISO 9001 or ISO/IEC 27001?", options: ["Clause 6.1.4 AI system impact assessment, which sits within the planning clause and has no direct counterpart in ISO 9001 or ISO/IEC 27001", "The requirement for AI-specific risk assessment and AI system impact assessment within Clause 8, along with the Annex A control framework for AI", "Clause 6.2 AI objectives, since management-system objectives in 9001 and 27001 are framed only as quality and information security objectives"], correct: 1, explanation: "ISO/IEC 42001 introduces AI-specific Clause 8 sub-clauses (8.2 risk assessment, 8.3 risk treatment, 8.4 impact assessment) and a unique Annex A. The first distractor names a real 42001-unique clause but is too narrow — the broader Clause 8 set plus Annex A is the more accurate distinction. The third distractor wrongly claims 6.2 is unique; 6.2 is the Annex SL objectives clause, present in both 9001 and 27001." },
      { question: "ISO/IEC 42001 contains four informative annexes (A through D). What is the relationship between Annex A and Annex B?", options: ["Annex A contains the control objectives and controls; Annex B provides implementation guidance for the controls listed in Annex A", "Annex A lists the reference controls used in the SoA; Annex B lists the AIMS objectives that controls are intended to achieve, drawn from Annex C", "Annex A applies to organizations developing AI systems; Annex B applies to organizations using AI systems supplied by others"], correct: 0, explanation: "Annex A defines the control set and Annex B explains how to implement those controls. The second distractor wrongly ties Annex B to AIMS objectives; objectives sit in 6.2 and Annex C, not Annex B. The third distractor invents a developer/user split that 42001 does not draw between annexes — both annexes apply to providers and users alike, and role distinctions are made elsewhere." },
      { question: "How does ISO/IEC 42001 Clause 8 differ from the typical Clause 8 in other Harmonized Structure standards?", options: ["It expands the operational planning structure with sub-clauses for AI system documentation and AI-specific deployment criteria not present in 9001 or 27001 Clause 8", "It introduces AI-specific operational requirements including AI risk assessment, AI risk treatment, and AI system impact assessment, which go beyond the generic operational planning found in other standards", "It restructures Clause 8 around the AI lifecycle phases (design, development, deployment, retirement), departing from the Annex SL operational-planning structure"], correct: 1, explanation: "42001's Clause 8 adds 8.2 AI risk assessment, 8.3 AI risk treatment, and 8.4 AI system impact assessment — operational counterparts to the Clause 6 planning sub-clauses. The first distractor cites the wrong sub-clauses; documentation/deployment are not the differentiators. The third distractor wrongly claims 42001 abandons the Annex SL structure; it follows Annex SL while adding AI-specific sub-clauses, not replacing the structure." },
      { question: "Which ISO/IEC 42001 annex provides guidance on AI-related organizational objectives and potential sources of risk?", options: ["Annex A for objectives (via control objectives) and Annex C for risk sources, since control objectives effectively define the achievable AI objectives", "Annex C, which provides guidance on AI-related organizational objectives, and Annex D, which provides potential sources of AI-related risk", "Annex B, which provides implementation guidance covering both objectives and risk sources alongside control implementation"], correct: 1, explanation: "Annex C lists potential AI-related objectives; Annex D lists potential sources of AI-related risk. The first distractor confuses Annex A control objectives with organizational AI objectives; they are different concepts. The third distractor wrongly bundles objectives and risk sources into Annex B; Annex B is implementation guidance for Annex A controls, not for objectives or risk sources." },
      { question: "An organization is implementing ISO/IEC 42001 and questions whether it must implement every control in Annex A. What is the correct interpretation?", options: ["All Annex A controls considered applicable by default must be implemented; exclusions require external auditor approval before being recorded in the SoA", "The organization determines which controls are applicable through its risk assessment and documents inclusions and exclusions with justification in the Statement of Applicability", "Annex A controls are mandatory by category — at least one control from each control area must be implemented, while individual controls within an area may be omitted"], correct: 1, explanation: "Annex A is a reference set; selection is driven by risk assessment and documented in the SoA with justification. The first distractor invents an external-approval step; certification bodies audit the SoA but do not pre-approve exclusions. The third distractor invents a per-category-minimum rule; 42001 does not require at least one control from each control area, applicability is decided by risk." },

      // Domain 3 – Planning (5 more to reach 20 with scenarios)
      { question: "An organization's context analysis identifies that a key competitor has suffered reputational damage from AI bias incidents. How should this be treated under Clause 4.1?", options: ["As a Clause 4.2 interested-party signal rather than a 4.1 issue, since the competitor is an interested party whose actions influence stakeholder expectations", "As an external issue that represents both a risk (similar incidents could occur internally) and an opportunity (to differentiate through responsible AI practices), informing the risk assessment and AI objectives", "As a Clause 6.1.1 risk-and-opportunity input bypassing 4.1, since competitor incidents only become relevant when they translate into specific risks during risk planning"], correct: 1, explanation: "Clause 4.1 captures external issues including competitor and market dynamics that affect the organization's purpose. The first distractor wrongly classifies a competitor as an interested party; competitors are typically captured as external issues under 4.1, not as IPs whose requirements feed 4.2. The third distractor skips 4.1 and goes straight to 6.1.1; the standard expects 4.1 issues to inform 6.1, not be replaced by it." },
      { question: "When planning changes to the AIMS under Clause 6.3, an organization proposes migrating all AI workloads to a new cloud provider. What must be considered?", options: ["The change must be subjected to a new full risk assessment under Clause 6.1.2 before any migration begins, since 6.3 cannot be invoked while a residual risk profile is unverified", "The purpose of the change, potential consequences for AIMS integrity, availability of resources, and allocation of responsibilities, including impacts on data governance, third-party risk, and AI system continuity", "Confirmation that the new provider's certifications cover ISO/IEC 27001 and ISO/IEC 42001, since 6.3 requires equivalence verification before changes are approved"], correct: 1, explanation: "Clause 6.3 explicitly lists purpose, consequences, AIMS integrity, resource availability, and responsibility allocation as considerations. The first distractor invents a sequencing rule that 6.3 must wait for a fresh full risk assessment; 6.3 itself triggers consideration of consequences and risks, not a separate 6.1.2 prerequisite. The third distractor invents an equivalence-verification mandate not contained in 6.3." },
      { question: "An organization sets an AI objective to 'improve AI fairness.' Why might an auditor flag this as non-conforming with Clause 6.2?", options: ["Clause 6.2 prohibits qualitative objectives such as fairness; AI objectives must be expressible as quantitative metrics agreed with affected parties", "The objective lacks specificity: Clause 6.2 requires AI objectives to be measurable where practicable, and 'improve AI fairness' does not define what will be measured, by how much, for which systems, or by when", "Fairness is listed in Annex C.2 as a potential objective topic, but Clause 6.2 requires objectives to be expressed at the AI system level, not the organizational level"], correct: 1, explanation: "Clause 6.2 requires objectives to be measurable where practicable, with planning to achieve them. The first distractor overstates: 6.2 says 'measurable where practicable' and accepts non-quantitative objectives when quantification is impractical. The third distractor invents a system-vs-organizational restriction; 6.2 sets AIMS-level objectives, and Annex C.2 is informative guidance on objective topics, not a clause-level mandate." },
      { question: "During risk assessment, two AI systems are identified with similar technical risk profiles but different affected populations—one serves enterprise clients and the other serves vulnerable individuals. How should this affect risk evaluation?", options: ["Both systems should receive identical risk ratings on technical likelihood and consequence, with the population factor recorded only as an Annex C.3 risk-source descriptor", "The risk evaluation should consider the nature and vulnerability of affected populations as a factor, potentially resulting in different risk levels despite similar technical profiles, as societal impact differs", "The system serving vulnerable individuals should receive a separate impact assessment under 6.1.4 only, with the underlying 6.1.2 risk rating remaining identical to the enterprise system"], correct: 1, explanation: "Risk evaluation under 6.1.2 must reflect AI-specific factors including impact on affected parties; vulnerability is part of consequence assessment, not a side note. The first distractor reduces the population factor to a descriptor; 42001 expects it to influence the rating itself. The third distractor wrongly separates 6.1.4 impact assessment from 6.1.2 risk rating; impact assessment informs risk rating, and the two systems should not share an identical 6.1.2 outcome." },
      { question: "An organization's AI policy states commitment to 'transparency in all AI operations.' During implementation, the team discovers that full transparency would compromise proprietary algorithms. How should this tension be resolved?", options: ["Issue a clarification under Clause 5.2 stating that 'transparency' refers exclusively to user-facing transparency about AI use, exempting proprietary algorithm disclosure", "Maintain the transparency commitment but define appropriate levels of transparency through risk treatment, distinguishing between transparency to affected parties about AI use and decisions versus disclosure of proprietary technical details", "Resolve the tension by tiering transparency through Annex A.8.2 information for users only, leaving Clause 5.2 policy text intact and unaddressed in operational documents"], correct: 1, explanation: "Transparency operates at multiple levels; risk treatment translates the commitment into proportionate disclosure. The first distractor narrows the policy commitment via a clarification; that risks substantively rewriting policy intent rather than operationalising it. The third distractor uses A.8.2 in isolation and bypasses risk-treatment integration; A.8.2 is one tool among several and should sit within the broader treatment plan." },

      // Domain 4 – Implementation (3 more to reach 18 with scenarios)
      { question: "An organization maintains AIMS documented information exclusively in a cloud-based collaboration platform. What Clause 7.5 consideration is most important?", options: ["Cloud-hosted documented information must be mirrored to on-premises storage at least quarterly, since 7.5.3 requires the organization to retain a locally controlled copy", "The organization must ensure appropriate controls for availability, access, integrity, and protection of documented information, including backup, version control, and access management regardless of the storage medium", "Cloud storage triggers automatic A.4.6 tooling controls that override 7.5.3, with availability and integrity managed through the cloud provider's SLA rather than the organization's own controls"], correct: 1, explanation: "Clause 7.5.3 requires controls for availability, distribution, access, retrieval, storage, version control, and disposition irrespective of medium. The first distractor invents an on-premises mirroring rule that 7.5.3 does not require. The third distractor wrongly transfers responsibility to the cloud SLA and to A.4.6; the organization remains accountable under 7.5.3 even when supplier services are used." },
      { question: "An AI system operates autonomously in production with no human-in-the-loop capability. What Annex A control consideration is most relevant?", options: ["Implementation of A.9.4 human oversight is mandatory for any deployed AI system, so the absence of human-in-the-loop is automatically a non-conforming control implementation", "The organization must evaluate whether the level of autonomy is appropriate given the system's risk profile, establish monitoring controls, and define intervention mechanisms proportionate to the potential impact of autonomous decisions", "Operating without human-in-the-loop requires switching from A.9.4 to A.9.3 system operation controls, since A.9.4 applies only to systems where humans are part of the inference loop"], correct: 1, explanation: "Annex A.9 controls require oversight proportionate to risk and impact; autonomy is not prohibited but must be justified and monitored. The first distractor wrongly absolutises A.9.4; the standard accepts a range of oversight modes calibrated to risk, including limited or post-hoc oversight. The third distractor invents a control-swapping rule between A.9.3 and A.9.4 that the standard does not establish; both apply alongside each other." },
      { question: "An organization's AI competence program focuses exclusively on technical ML skills for data scientists. What aspect of Clause 7.2 is being overlooked?", options: ["Technical ML skills should be supplemented by ISO/IEC 27001 information security training for data scientists, since 7.2 requires multi-standard competence for personnel in dual-certified organizations", "Clause 7.2 requires competence for all persons whose work affects AI system performance, including non-technical roles such as product managers, business analysts, and operational staff who need understanding of AI ethics, governance, and organizational AI policy", "Clause 7.2 also requires personnel to obtain ISO/IEC 17024 certification in AI competence before being deemed competent under the AIMS"], correct: 1, explanation: "7.2 covers all persons whose work affects AI performance — including non-technical roles. The first distractor narrows competence to ML-plus-ISMS for data scientists; the gap is broader and includes non-technical roles. The third distractor invents an ISO/IEC 17024 certification requirement; 17024 governs persons-certification bodies but does not impose certification on personnel under 42001." },

      // Domain 5 – Monitoring (3 more to reach 10 with scenarios)
      { question: "During management review, top management requests that AI performance reports focus only on positive metrics and exclude incidents. What should the AIMS manager do?", options: ["Provide the requested positive metrics and route the incident information through a separate Clause 9.1 monitoring report to top management outside the management-review meeting", "Explain that Clause 9.3 requires management review to consider specific inputs including nonconformities and corrective actions, and that omitting negative information would result in non-conformity and undermine AIMS effectiveness", "Reformulate the incident data as opportunities for improvement under Clause 10.1, allowing top management to receive the same information without breaching 9.3 input requirements"], correct: 1, explanation: "Clause 9.3 mandates inputs including NC and corrective actions; selectively withholding them is non-conformity. The first distractor wrongly splits review inputs across separate channels; 9.3 inputs must be considered within the management review itself. The third distractor relabels NCs as opportunities to placate management — a reframing that distorts the AIMS record and still bypasses the 9.3 NC input requirement." },
      { question: "An organization monitors individual AI model performance but does not assess overall AIMS effectiveness. What is missing from their Clause 9.1 implementation?", options: ["A consolidated dashboard combining individual model metrics into an aggregate AIMS effectiveness score, calculated as a weighted average per the organization's risk methodology", "The organization needs to evaluate the effectiveness of the AIMS as a management system, including process effectiveness, control adequacy, risk treatment outcomes, and progress toward AI objectives, not solely individual model metrics", "Verification of model metrics against ISO/IEC 23053 reference benchmarks, which 9.1 requires before AIMS effectiveness can be determined"], correct: 1, explanation: "9.1 requires monitoring AIMS process effectiveness alongside AI system performance; aggregating model metrics is not a substitute. The first distractor reduces effectiveness to a weighted dashboard; AIMS effectiveness includes processes, controls, treatment outcomes, and objective progress beyond model metrics. The third distractor misuses ISO/IEC 23053; 23053 is a framework reference, not a 9.1 mandatory benchmark." },
      { question: "Internal audit findings from the previous cycle identified three minor nonconformities. At the current management review, the AIMS manager reports that all three have been closed. What additional information should be provided?", options: ["The cost of corrective action implementation per finding, since 9.3 requires resource adequacy review tied to specific corrective actions", "Evidence that the corrective actions were effective in preventing recurrence, trends in nonconformity types, and whether additional systemic improvements are indicated", "Confirmation that the audits' lead auditor has signed off the closure, since 9.3 requires auditor attestation as a management-review input"], correct: 1, explanation: "9.3 inputs include effectiveness of corrective actions and trends, not just closure. The first distractor narrows to cost; resource adequacy is one 9.3 input among many, and cost-per-finding is not the headline missing item. The third distractor invents an auditor-attestation requirement; 9.3 requires inputs about effectiveness and trends, not lead-auditor sign-off as a formal artefact." },

      // Domain 6 – Improvement & certification (2 more to reach 10 with scenarios)
      { question: "During a surveillance audit, the auditor discovers that the organization has significantly expanded its AI operations but not updated the certified AIMS scope. What action should the certification body consider?", options: ["Issue a minor nonconformity under Clause 4.3 to be closed at the next surveillance audit, since scope drift between audits is a known maintenance issue rather than an immediate certification concern", "Evaluate whether the scope change is significant enough to require a special audit or scope extension audit, as the current certificate may not accurately represent the organization's AIMS", "Suspend the certificate immediately under ISO/IEC 17021-1 until the organization re-applies for a full Stage 1 plus Stage 2 audit covering the expanded operations"], correct: 1, explanation: "Significant operational changes may warrant a special audit or scope extension; the certification body assesses materiality. The first distractor downgrades the issue to routine surveillance closure; significant scope drift typically requires more than a minor NC. The third distractor escalates to immediate suspension and a fresh Stage 1/Stage 2; 17021-1 supports proportionate responses including special audits before suspension." },
      { question: "An organization achieves ISO/IEC 42001 certification and then makes no changes to its AIMS for three years, arguing that stability demonstrates maturity. What AIMS requirement does this potentially violate?", options: ["Clause 6.3 changes to the AIMS, since the absence of change indicates the organization has not planned any changes during the certification cycle as 6.3 requires", "Clause 10.1 requires continual improvement of AIMS suitability, adequacy, and effectiveness; a completely static system in a rapidly evolving AI landscape suggests the organization is not adapting to changes in technology, risks, or best practices", "Clause 9.3 only, since management review must produce decisions for change, and the absence of changes implies that management review has not occurred for three years"], correct: 1, explanation: "Clause 10.1 (continual improvement) is the principal requirement; static AIMS in a dynamic field suggests stagnation. The first distractor inverts 6.3: 6.3 governs how planned changes are managed, not a mandate to make changes. The third distractor wrongly equates absence of change with absence of management review; reviews can occur without producing change decisions, although a three-year flat outcome is suspect under 10.1, not 9.3." },

      // Additional questions for domain balance
      { question: "An organization identifies that its AI system's training pipeline uses open-source libraries with known vulnerabilities. Under which AIMS consideration should this be addressed?", options: ["Through the ISO/IEC 27001 ISMS interface alone, since library vulnerabilities are CVE-tracked information security issues and not AI-specific risks under 42001", "As part of the AI risk assessment process, since vulnerable components in the AI pipeline can compromise model integrity, data quality, and system reliability, affecting the AI system's trustworthiness", "Through Clause 8.1 operational change management only, by pinning library versions and deferring vulnerability remediation to scheduled maintenance windows"], correct: 1, explanation: "Vulnerable components affect AI integrity and trustworthiness; 8.2 risk assessment must address them, with the ISMS interface as a related mechanism. The first distractor wrongly excludes 42001; vulnerabilities affecting model integrity are AI-specific risks. The third distractor reduces the issue to change management with version pinning; pinning preserves a known-vulnerable state and does not satisfy risk assessment and treatment." },
      { question: "A certification body discovers during Stage 2 that the organization implemented additional Annex A controls beyond those listed in its SoA. Is this a nonconformity?", options: ["Yes, the SoA is the definitive list of applicable controls; controls implemented outside the SoA are unaccounted-for activities and must be classified as a minor nonconformity", "Not inherently a nonconformity in terms of control implementation, but the SoA should accurately reflect the organization's control decisions; the SoA should be updated to include all implemented controls with their justification", "No, the SoA is a planning artefact only; once Stage 2 begins, control implementation evidence supersedes the SoA and discrepancies are resolved by updating audit records rather than the SoA"], correct: 1, explanation: "Implementing extra controls is positive, but the SoA must remain accurate; the substantive issue is SoA fidelity, not implementation. The first distractor over-classifies the issue as an NC for the implementation; 42001 does not penalise additional implementation. The third distractor wrongly demotes the SoA to a planning artefact; the SoA is a living document and must be kept accurate to reflect current control decisions." },
      { question: "An organization's Clause 7.4 communication plan addresses internal communication about the AIMS but does not include external communication procedures. Is this sufficient?", options: ["Yes, where the organization has an enterprise-level external-communications policy, 7.4 permits referencing that policy without restating external procedures within the AIMS", "No, Clause 7.4 requires the organization to determine both internal and external communications relevant to the AIMS, including what, when, with whom, and how to communicate", "Yes, provided Annex A.3.3 reporting concerns is implemented, since A.3.3 covers all external communication needs under 42001"], correct: 1, explanation: "Clause 7.4 explicitly requires determining internal and external communications and the parameters for each. The first distractor allows blanket reference to an enterprise policy; 7.4 still requires the AIMS to determine its own external communication needs even if it leverages enterprise mechanisms. The third distractor wrongly substitutes A.3.3 for 7.4; A.3.3 covers reporting concerns, which is one channel, not the full external-communications scope." },
      { question: "During an AI system impact assessment under Clause 8.4, an organization evaluates only the direct technical impacts of the AI system. What broader impacts should be assessed?", options: ["Direct technical impacts plus deployment-context impacts on operators and direct users, with broader societal effects deferred to 8.4 cycles after the system reaches production scale", "Broader impacts including effects on individuals and groups (such as fairness, privacy, and autonomy), societal impacts, economic impacts, and environmental impacts, consistent with ISO/IEC 42005 guidance", "Direct technical impacts and intellectual property impacts, since 8.4 prioritizes IP risk while ISO/IEC 42005 addresses other impact categories outside 42001"], correct: 1, explanation: "8.4 impact assessment, supported by ISO/IEC 42005 guidance, should cover impacts on individuals, groups, society, economy, and environment. The first distractor wrongly defers societal impact to post-scale cycles; 8.4 expects broader impact assessment from the start. The third distractor narrows 8.4 to technical and IP impacts, treating 42005 as out-of-scope; 42005 is the guidance document for the breadth of 8.4 itself." },
      { question: "An organization plans to use synthetic data to augment its training dataset. What AIMS consideration is most important?", options: ["Synthetic data is governed by separate controls under A.7.6 and is exempt from A.7.4 quality and A.7.5 acquisition, simplifying the data governance framework", "The organization must assess the quality and representativeness of synthetic data, evaluate whether it introduces biases or artifacts that could affect model performance, and document the synthetic data generation process within its data governance framework", "Synthetic data must be benchmarked against real-data baselines monthly, with retraining triggered automatically whenever synthetic-vs-real performance gaps exceed defined thresholds"], correct: 1, explanation: "Synthetic data must be assessed for quality, representativeness, bias, and artefacts, with generation documented in the data governance framework. The first distractor wrongly exempts synthetic data from A.7.4/A.7.5; synthetic data is in scope for the same data-governance controls. The third distractor invents a monthly-benchmark and auto-retrain rule that 42001 does not impose; cadence is determined by the organization's risk-based monitoring, not a fixed mandate." }
    ]}
  ]
};
